      unconfirmed = false,
      flag = "",
      sources = { "https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-october-15/2360696", "https://www.wowhead.com/forever/guide/classes/paladin/retribution/dps-leveling-tips", "https://news.blizzard.com/en-us/article/24302099/world-of-warcraft-forever-class-deep-dives-paladin" },
