      sources = { "https://static.icy-veins.com/r2/icydb/wowf/talents/70888-1d81729b/paladin.json", "https://www.wowhead.com/forever/guide/classes/paladin/retribution/dps-leveling-tips", "https://www.wowhead.com/forever/guide/classes/paladin/protection/tank-leveling-tips" },
